Here is the commit message:
popover: Take shadow size into account in measure

Commit b9487997 introduced shadows for GtkPopover. These are correctly
subtracted while allocating the child widget, but the child is not
measured with those shadows subtracted (as is correctly done for the
arrow). This can give criticals, for example with some wrapping labels.

To fix this, we subtract the shadow size from the `for_size` before
passing it to the measure() of the child widget.

Closes #5782
Fixes #6796

Here is the root cause:
The bug was caused by the `gtk_popover_measure` function not accounting for the shadow size when measuring the dimensions of the child widget. While the shadow size was correctly subtracted during the allocation of the child widget, it was not considered during the measurement phase, leading to potential critical issues, especially with wrapping labels.

Here is the patch:

 static void
 gtk_popover_measure (GtkWidget      *widget,
                      GtkOrientation  orientation,
                      int             for_size,
                      int            *minimum,
                      int            *natural,
                      int            *minimum_baseline,
                      int            *natural_baseline)
 {
   GtkPopover *popover = GTK_POPOVER (widget);
   GtkPopoverPrivate *priv = gtk_popover_get_instance_private (popover);
   int minimal_size;
   int tail_height = priv->has_arrow ? TAIL_HEIGHT : 0;
   GtkCssStyle *style;
   GtkBorder shadow_width;

-  if (for_size >= 0 && (POS_IS_VERTICAL (priv->position) == (orientation == GTK_ORIENTATION_HORIZONTAL)))
-    for_size -= tail_height;
-
   style = gtk_css_node_get_style (gtk_widget_get_css_node (GTK_WIDGET (priv->contents_widget)));
   gtk_css_shadow_value_get_extents (style->used->box_shadow, &shadow_width);

+  if (for_size >= 0)
+    {
+      if ((POS_IS_VERTICAL (priv->position) == (orientation == GTK_ORIENTATION_HORIZONTAL)))
+        for_size -= tail_height;
+
+      if (orientation == GTK_ORIENTATION_HORIZONTAL)
+        for_size -= shadow_width.top + shadow_width.bottom;
+      else
+        for_size -= shadow_width.left + shadow_width.right;
+    }
+
   gtk_widget_measure (priv->contents_widget,
                       orientation, for_size,
                       minimum, natural,
                       minimum_baseline, natural_baseline);

   minimal_size = get_minimal_size (popover, orientation);
   *minimum = MAX (*minimum, minimal_size);
   *natural = MAX (*natural, minimal_size);

   if (orientation == GTK_ORIENTATION_HORIZONTAL)
     {
       *minimum += shadow_width.left + shadow_width.right;
       *natural += shadow_width.left + shadow_width.right;
     }
   else
     {
       *minimum += shadow_width.top + shadow_width.bottom;
       *natural += shadow_width.top + shadow_width.bottom;
     }

   if (POS_IS_VERTICAL (priv->position) == (orientation == GTK_ORIENTATION_VERTICAL))
     {
       *minimum += tail_height;
       *natural += tail_height;
     }
 }



